INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4972158, 27064, '/rz7vhePVk3zHtgfTKoF7BovgjJk.jpg', 'In a stark black-and-white woodland, a shirtless, sweat-slicked man in a loose white loincloth stands bound by his wrists to a tree, an arrow piercing his side, evoking the Saint Sebastian-like martyrdom image from Mishima''s imagined, aestheticized vision of suffering and beauty.', 'claude-sonnet-5-5')
ON DUPLICATE KEY UPDATE CAPTION=VALUES(CAPTION), TIM_UPDATED=CURRENT_TIMESTAMP;
INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 900368, 36872, '/uhBqLIBDcC9hjg82RNInb2UozHl.jpg', 'Hideko Takamine as Keiko, the weary Ginza hostess, stands in a heavy wool coat and patterned scarf, gazing off with a solemn, guarded expression against a bleak industrial skyline of smokestacks and low rooftops in black and white.', 'claude-sonnet-5-5')
ON DUPLICATE KEY UPDATE CAPTION=VALUES(CAPTION), TIM_UPDATED=CURRENT_TIMESTAMP;
INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 900366, 36872, '/zmmHet7uAWG5TeKFFgFXHLnHvEs.jpg', 'Keiko (Hideko Takamine), the Ginza bar hostess known as Mama, sits composed in a striped kimono and fluffy white shawl, glancing aside with a faint, practiced smile as staff move past a "Lavatory" door in the softly lit, black-and-white bar.', 'claude-sonnet-5-5')
ON DUPLICATE KEY UPDATE CAPTION=VALUES(CAPTION), TIM_UPDATED=CURRENT_TIMESTAMP;
INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 1191622, 20482, '/jKiKToIcEpHoRLXzZ8tw1jtPOLk.jpg', 'Detectives, a police photographer with a raised flash, and a uniformed officer crowd around a bed in Jean Dexter''s bedroom as they examine the scene of her apparent accidental death, in a stark, clinical black-and-white investigation.', 'claude-sonnet-5-5')
ON DUPLICATE KEY UPDATE CAPTION=VALUES(CAPTION), TIM_UPDATED=CURRENT_TIMESTAMP;
INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4972136, 27064, '/8OkbEyJZmKS3X0zCDjvyvdH8yNU.jpg', 'A stylized, theatrical torii gate stands on a pale gravel plain under a swirling painted sky, while uniformed Tatenokai cadets in dark caps line up in silhouette behind it, evoking the ritualistic, heightened mood of Mishima''s final day.', 'claude-sonnet-5-5')
ON DUPLICATE KEY UPDATE CAPTION=VALUES(CAPTION), TIM_UPDATED=CURRENT_TIMESTAMP;
INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4116741, 31527, '/pBGX7leFXZmWgjbhUqQQgLwSjKv.jpg', 'Marlene Dietrich as Sophia Frederica, the future Catherine the Great, gazes softly through a gilded frame in a hazy black-and-white close-up, her face veiled by delicate blossoms and draped fabric, in a dreamy, romantic and slightly mysterious mood.', 'claude-sonnet-5-5')
ON DUPLICATE KEY UPDATE CAPTION=VALUES(CAPTION), TIM_UPDATED=CURRENT_TIMESTAMP;
INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4972164, 27064, '/d3Hq8grKa27WoWWspWSfyfKDJcf.jpg', 'Rows of young men in black uniforms stand with their backs to us on a pale gravel expanse, facing a small white Shinto-style shrine beneath a vivid, stylized sky, in one of Mishima''s theatrical, dreamlike stage-set scenes.', 'claude-sonnet-5-5')
