INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 900363, 36872, '/tqvnKbGqrznKGikp01mkNG7ZOaY.jpg', 'In a black-and-white shot set against blurred Ginza shop lights, Keiko (Hideko Takamine), in a striped kimono, gazes calmly at the camera while Komatsu (Tatsuya Nakadai), in a suit and tie, stands close behind her and glances warily aside.', 'claude-sonnet-5-5')
ON DUPLICATE KEY UPDATE CAPTION=VALUES(CAPTION), TIM_UPDATED=CURRENT_TIMESTAMP;
INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 900357, 36872, '/uSyVJvqo7EwFguVukPIPa00dLAk.jpg', 'In stark black-and-white, Keiko (Hideko Takamine), dressed in a striped kimono with an ornate obi, pauses on the dim carpeted staircase to her Ginza bar, her head bowed in a quiet, weary moment before putting on her cheerful hostess mask.', 'claude-sonnet-5-5')
