INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 424606, 93, '/buQNfkqSZPFIoxFxSqaTRt0afCI.jpg', 'A black-and-white shot of a jazz quartet in tuxedos performing in the inn''s lounge in Anatomy of a Murder, with a drummer, upright bassist, trumpeter and saxophonist playing together in a smoky, intimate nightclub mood.', 'claude-sonnet-5-5')
