INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4972147, 27064, '/chLHE6wFaQI9C20pxz3D1W6rsxU.jpg', 'In the stylized Temple of the Golden Pavilion dramatization, a man in a white shirt sweeps with a straw broom beside a gleaming golden temple set, surrounded by crimson fallen leaves and a painted backdrop in a theatrical, dreamlike mood.', 'claude-sonnet-5-5')
