INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 424605, 93, '/vaR4hPeWrbQ7ZXuoQULd98ejt2H.jpg', 'In the bar of Quill''s inn, Paul Biegler (James Stewart), in a fedora and suit, sits at the counter and questions bartender Alphonse Paquette (Murray Hamilton), who wipes a glass with a cloth and avoids his gaze, in a tense black-and-white scene.', 'claude-sonnet-5-5')
