INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 1191625, 20482, '/mp4QTTibxAESRrEFO3xWV4zUTui.jpg', 'A woman bites her knuckle and stares anxiously past a newspaper whose headline reads "Young Model Found Slain In Bathtub," with Jean Dexter''s smiling photo beside her, capturing the shock of the murder news in this black-and-white New York noir.', 'claude-sonnet-5-5')
