INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4207693, 93, '/z3mfEQmPsTU5ieksw41gbYY9Ylm.jpg', 'In a packed courtroom, Paul Biegler (James Stewart) sits chin on hand at the defense table beside Lt. Manion (Ben Gazzara) in uniform and Laura Manion, while Parnell McCarthy and Maida Rutledge lean in to whisper urgently.', 'claude-sonnet-5-5')
