INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 1191626, 20482, '/j8jfHP5ImgfZG1bHdA5yK3zb9Bs.jpg', 'Shirtless boys in swim trunks stand on pilings at the edge of the East River, poised to dive while two swimmers float below, with a steel bridge and barges hazy in the background of this sweltering summer New York day in The Naked City.', 'claude-sonnet-5-5')
