INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4972157, 27064, '/2EhAwvLnCGRbE2JiGYup5rSSHe3.jpg', 'A stylized, empty low-table dining room with giant painted orchids on three pale walls and lilac floor cushions, a theatrical set evoking the artificial, hyper-aestheticized world of the Kyoko''s House dramatization in Schrader''s film.', 'claude-sonnet-5-5')
