INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4972143, 27064, '/tK6TLLHLWTyCLhSpkr1Am6axUlJ.jpg', 'Two dark-clad figures stand on green walkways before a glowing golden model of the Kinkaku-ji pavilion, in the stylized gilded studio set of the Temple of the Golden Pavilion dramatization, with painted hills and lotus blossoms behind them.', 'claude-sonnet-5-5')
