INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4972153, 27064, '/7l5kh1ngK4GPMfLuBDGrNbziKNZ.jpg', 'A gleaming gold-leaf stage set of the Golden Pavilion, split in two against painted green hills and lotus leaves, evokes the stylized Temple of the Golden Pavilion dramatization in Schrader''s Mishima, with a luminous, dreamlike, obsessive mood.', 'claude-sonnet-5-5')
