INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 3676176, 4269, '/3LTHrUf88NkZSeNT2UdgJ5IV4cw.jpg', 'Danielle Darrieux''s Madame Langlois, the widowed former baroness, sits smoking at her grand piano in her opulent red-walled salon, surrounded by chandeliers, gilt mirrors and lamps, in a quiet, melancholy, faded-aristocratic mood.', 'claude-sonnet-5-5')
