INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 1191628, 20482, '/4fBoH36P1mLI0yD9dMSJaTV7kx8.jpg', 'A trashman in a cap walks away from the camera along a dark Times Square street, lit by neon signs for Hotel Astor, Kinsey, Bond and Vaudeville, in the film''s closing New York night montage of the city carrying on after the case.', 'claude-sonnet-5-5')
